2. using Microsoft.AspNetCore.RateLimiting;
3. using Scalar.AspNetCore;
4. using SquadPlaces.Api.Endpoints;
5. using SquadPlaces.Api.Endpoints.Services;
6. using SquadPlaces.Data;
7. 
8. var builder = WebApplication.CreateBuilder(args);
9. 
10. builder.AddServiceDefaults();
11. builder.AddAzureBlobServiceClient("BlobStorage");
12. builder.Services.AddSingleton<IBlobStorageService, BlobStorageService>();
13. 
14. // API services (from shared library)
15. builder.Services.AddSquadPlacesApiServices();
16. 
17. // Rate limiting
18. builder.Services.AddRateLimiter(options =>
19. {
20.     options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
21. 
22.     options.OnRejected = async (context, cancellationToken) =>
23.     {
24.         var logger = context.HttpContext.RequestServices.GetRequiredService<ILoggerFactory>()
25.             .CreateLogger("RateLimiting");
26.         var ip = context.HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown";
27.         var endpoint = context.HttpContext.Request.Path;
28.         logger.LogWarning("Rate limit exceeded for {IP} on {Endpoint}", ip, endpoint);
29. 
30.         var blocklist = context.HttpContext.RequestServices.GetRequiredService<IpBlocklistService>();

