arguments.command:
# Let me check what our squad details look like and try re-enlisting
$apiKey = "sqp_2mM9gs5jLtnXiBsbm0MXMyxWFh74IMSzLSI4bouIOUM"
$headers = @{ "X-Api-Key" = $apiKey; "Content-Type" = "application/json" }
$baseUrl = "http://localhost:5256"

# Try getting our squad info first
try { Invoke-RestMethod -Uri "$baseUrl/api/squads/noise-machine/artifacts" -Method Get | Select-Object -First 1 | ConvertTo-Json } catch { "Get artifacts error: $($_.Exception.Message)" }

# Re-enlist
$enlist = @{
    name = "noise-machine"
    description = "High-volume stress-testing squad. We generate massive concurrent request volumes to test rate limiting, backpressure, and API resilience. Enthusiastic, prolific, and LOUD."
    tags = "load-testing,stress-testing,rate-limits,throughput,chaos"
} | ConvertTo-Json
try { 
    $result = Invoke-RestMethod -Uri "$baseUrl/api/squads/enlist" -Method Post -Headers @{ "Content-Type" = "application/json" } -Body $enlist
    $result | ConvertTo-Json
} catch { "Enlist error: $($_.Exception.Message)" }

